class TempLog:
    def __init__(self):
        self.temps = []

    def add(self, temp):
        self.temps.append(temp)

    def average(self):
        if not self.temps:
            return None
        return round(sum(self.temps) / len(self.temps), 1)

    def highest(self):
        if not self.temps:
            return None
        return max(self.temps)

class Editor:
    def __init__(self):
        self.text = ""
        self.history = []

    def write(self, words):
        self.history.append(self.text)
        self.text += words

    def undo(self):
        if self.history:
            self.text = self.history.pop()

class Timer:
    def __init__(self):
        self.started = None
        self.laps = []

    def start(self, t):
        if self.started is not None:
            raise RuntimeError("Already running")
        self.started = t

    def stop(self, t):
        if self.started is None:
            raise RuntimeError("Not running")
        self.laps.append(t - self.started)
        self.started = None

    def total(self):
        return sum(self.laps)

