class Inventory:
    def __init__(self):
        self._stock = {}

    def add(self, item, qty):
        self._stock[item] = self._stock.get(item, 0) + qty

    def count(self, item):
        return self._stock.get(item, 0)

    def _check(self, item, qty):
        if self.count(item) < qty:
            raise ValueError(f"Not enough {item}")

    def remove(self, item, qty):
        self._check(item, qty)
        self._stock[item] -= qty

    def remove_many(self, order):
        for item, qty in order.items():
            self._check(item, qty)
        for item, qty in order.items():
            self._stock[item] -= qty

