class Order:
    def __init__(self):
        self._lines = []
        self._closed = False

    def add(self, item, price):
        if self._closed:
            raise RuntimeError("Order is closed")
        self._lines.append((item, price))

    def total(self):
        return sum(price for item, price in self._lines)

    def items(self):
        return tuple(item for item, price in self._lines)

    def close(self):
        if not self._lines:
            raise ValueError("Order is empty")
        self._closed = True

