challenges.solution:
class User:
    def __init__(self, email):
        self.email = email

    @property
    def email(self):
        return self._email

    @email.setter
    def email(self, value):
        cleaned = value.strip().lower()
        if "@" not in cleaned:
            raise ValueError(f"Bad email: {value}")
        self._email = cleaned

