challenges.solution:
class Basket:
    def __init__(self):
        self.items = []

    def add(self, name, price):
        self.items.append((name, price))

    @property
    def total(self):
        return sum(price for name, price in self.items)

    @property
    def count(self):
        return len(self.items)

    @property
    def is_empty(self):
        return not self.items

class Task:
    def __init__(self, total):
        self.total = total
        self.done = 0

    @property
    def done(self):
        return self._done

    @done.setter
    def done(self, value):
        self._done = max(0, min(self.total, value))

    @property
    def percent(self):
        return self.done * 100 // self.total

    @property
    def bar(self):
        filled = self.percent // 10
        return "[" + "#" * filled + "-" * (10 - filled) + f"] {self.percent}%"

class Duration:
    def __init__(self, seconds):
        self.total_seconds = seconds

    @property
    def total_seconds(self):
        return self._total

    @total_seconds.setter
    def total_seconds(self, value):
        if value < 0:
            raise ValueError("Duration can't be negative")
        self._total = value

    @property
    def hours(self):
        return self._total // 3600

    @property
    def minutes(self):
        return self._total % 3600 // 60

    @property
    def seconds(self):
        return self._total % 60

    def __str__(self):
        return f"{self.hours}:{self.minutes:02d}:{self.seconds:02d}"

