            raise ValueError(f"{vehicle.plate} is already parked")
        if self.free_spaces() == 0:
            raise ValueError("Garage full")
        self.parked[vehicle.plate] = (vehicle, time)

    def leave(self, plate, time):
        if plate not in self.parked:
            raise ValueError(f"{plate} isn't parked here")
        vehicle, arrived = self.parked[plate]
        if time < arrived:
            raise ValueError("Can't leave before arriving")
        del self.parked[plate]
        fee = vehicle.fee(time - arrived)
        self.takings += fee
        return fee

