        return lines


KINDS = {"motorbike": Motorbike, "car": Car, "van": Van}


def run(garage, events):
    output = []
    for event in events:
        words = event.split()
        try:
            if words[0] == "park":
                kind, plate, time = words[1], words[2], float(words[3])
                if kind not in KINDS:
                    raise ValueError(f"Unknown vehicle: {kind}")
                garage.park(KINDS[kind](plate), time)
                output.append(f"Parked {plate}")
            elif words[0] == "leave":
                plate, time = words[1], float(words[2])
                fee = garage.leave(plate, time)
                output.append(f"{plate} paid {fee:.2f}")
            else:
                output.append(f"Unknown event: {event}")
        except ValueError as e:
            output.append(str(e))
    return output

