class Character:
    def __init__(self, name, hp, attack, defense):
        self.name = name
        self.max_hp = hp
        self.hp = hp
        self.attack = attack
        self.defense = defense

    @property
    def is_alive(self):
        return self.hp > 0

    def take_damage(self, amount):
        taken = min(amount, self.hp)
        self.hp -= taken
        return taken

    def __str__(self):
        return f"{self.name} ({self.hp}/{self.max_hp} hp)"

    def hit(self, other):
        damage = other.take_damage(max(1, self.attack - other.defense))
        return f"{self.name} hits {other.name} for {damage} ({other.name}: {other.hp} hp)"


class Hero(Character):
    def __init__(self, name, hp, attack, defense, potions=2):
        super().__init__(name, hp, attack, defense)
        self.potions = potions

    def heal(self):
        if self.potions == 0:
            return f"{self.name} has no potions left"
        self.potions -= 1
        self.hp = min(self.max_hp, self.hp + 10)
        return f"{self.name} drinks a potion ({self.hp} hp)"


class Mage(Character):
    def __init__(self, name, hp, attack, defense, mana=10):
        super().__init__(name, hp, attack, defense)
        self.mana = mana

    def hit(self, other):
        if self.mana < 5:
            return super().hit(other)
        self.mana -= 5
        damage = other.take_damage(self.attack * 2)
        return f"{self.name} casts a fireball at {other.name} for {damage} ({other.name}: {other.hp} hp)"


class Battle:
    def __init__(self, heroes, monsters):
        self.heroes = heroes
        self.monsters = monsters

    @staticmethod
    def first_alive(side):
        for character in side:
            if character.is_alive:
                return character
        return None

    def round(self):
        log = []
        for attackers, defenders in [(self.heroes, self.monsters), (self.monsters, self.heroes)]:
            for attacker in attackers:
                target = self.first_alive(defenders)
                if attacker.is_alive and target is not None:
                    log.append(attacker.hit(target))
        return log

    def fight(self, max_rounds=20):
        log = []
        for number in range(1, max_rounds + 1):
            log.append(f"Round {number}")
            log.extend(self.round())
            if self.first_alive(self.monsters) is None:
                log.append("The heroes win!")
                return log
            if self.first_alive(self.heroes) is None:
                log.append("The monsters win!")
                return log
        log.append("Nobody wins")
        return log
